#define TMR_SPAN                           0x20u
#define TMR_AT(n)                          (0x140u + (n) * TMR_SPAN)
#define TMR_CTRL_OFS                       0x0u
#define TMR_CTRL(n)                        HW_REG32(SYSTEM_BASE + TMR_AT(n) + TMR_CTRL_OFS)
#define TMR_CTRL_EN_SHIFT                  0
#define TMR_CTRL_EN_MASK                   0x1u
#define TMR_CTRL_REPEAT_SHIFT              1
#define TMR_CTRL_REPEAT_MASK               0x2u
#define TMR_CTRL_SRC_SHIFT                 2
#define TMR_CTRL_SRC_MASK                  0xCu
#define TMR_CTRL_IRQ_SHIFT                 4
#define TMR_CTRL_IRQ_MASK                  0x10u
#define TMR_CTRL_DMA_SHIFT                 5
#define TMR_CTRL_DMA_MASK                  0x20u
#define TMR_CTRL_DMACH_SHIFT               6
#define TMR_CTRL_DMACH_MASK                0xC0u
#define TMR_PRESCALE_OFS                   0x4u
#define TMR_PRESCALE(n)                    HW_REG32(SYSTEM_BASE + TMR_AT(n) + TMR_PRESCALE_OFS)
#define TMR_PRESCALE_DIV_SHIFT             0
#define TMR_PRESCALE_DIV_MASK              0xFFFFu
#define TMR_RELOAD_OFS                     0x8u
#define TMR_RELOAD(n)                      HW_REG32(SYSTEM_BASE + TMR_AT(n) + TMR_RELOAD_OFS)
#define TMR_COUNT_OFS                      0xCu
#define TMR_COUNT(n)                       HW_REG32(SYSTEM_BASE + TMR_AT(n) + TMR_COUNT_OFS)
#define TMR_STAT_OFS                       0x10u
#define TMR_STAT(n)                        HW_REG32(SYSTEM_BASE + TMR_AT(n) + TMR_STAT_OFS)
#define TMR_STAT_UNDER_SHIFT               0
#define TMR_STAT_UNDER_MASK                0x1u

/* ---- DMXDESC: 32-byte layout in memory, spec 11/3 */
typedef struct {
    uint32_t ctrl;
    uint32_t src;
    uint32_t dst;
    uint32_t width;
    uint32_t height;
    uint32_t stride;
    uint32_t value;
    uint32_t next;
} dmxdesc_t;
_Static_assert(sizeof(dmxdesc_t) == 32, "DMXDESC layout");
#define DMXDESC_SIZEOF                     32
#define DMXDESC_CTRL_OFS                   0x0u
#define DMXDESC_CTRL_OP_SHIFT              0
#define DMXDESC_CTRL_OP_MASK               0x7u
#define DMXDESC_CTRL_FN_SHIFT              4
#define DMXDESC_CTRL_FN_MASK               0xF0u
#define DMXDESC_CTRL_BPP_SHIFT             8
#define DMXDESC_CTRL_BPP_MASK              0x300u
#define DMXDESC_CTRL_DESC_SHIFT            10
#define DMXDESC_CTRL_DESC_MASK             0x400u
#define DMXDESC_CTRL_HIGH_SHIFT            11
#define DMXDESC_CTRL_HIGH_MASK             0x800u
#define DMXDESC_CTRL_IRQ_SHIFT             12
#define DMXDESC_CTRL_IRQ_MASK              0x1000u
#define DMXDESC_CTRL_SRCKIND_SHIFT         13
#define DMXDESC_CTRL_SRCKIND_MASK          0x6000u
#define DMXDESC_CTRL_DSTKIND_SHIFT         15
#define DMXDESC_CTRL_DSTKIND_MASK          0x18000u
#define DMXDESC_SRC_OFS                    0x4u
#define DMXDESC_SRC_ADDR_SHIFT             0
#define DMXDESC_SRC_ADDR_MASK              0xFFFFFFu
#define DMXDESC_DST_OFS                    0x8u
#define DMXDESC_DST_ADDR_SHIFT             0
#define DMXDESC_DST_ADDR_MASK              0xFFFFFFu
#define DMXDESC_WIDTH_OFS                  0xCu
#define DMXDESC_WIDTH_COUNT_SHIFT          0
#define DMXDESC_WIDTH_COUNT_MASK           0xFFFFFFu
#define DMXDESC_HEIGHT_OFS                 0x10u
#define DMXDESC_HEIGHT_ROWS_SHIFT          0
#define DMXDESC_HEIGHT_ROWS_MASK           0xFFFFu
#define DMXDESC_HEIGHT_SRCBIT_SHIFT        16
#define DMXDESC_HEIGHT_SRCBIT_MASK         0x70000u
#define DMXDESC_HEIGHT_DSTBIT_SHIFT        20
#define DMXDESC_HEIGHT_DSTBIT_MASK         0x700000u
#define DMXDESC_STRIDE_OFS                 0x14u
#define DMXDESC_STRIDE_SRCSTRIDE_SHIFT     16
#define DMXDESC_STRIDE_SRCSTRIDE_MASK      0xFFFF0000u
#define DMXDESC_STRIDE_DSTSTRIDE_SHIFT     0
#define DMXDESC_STRIDE_DSTSTRIDE_MASK      0xFFFFu
#define DMXDESC_VALUE_OFS                  0x18u
#define DMXDESC_NEXT_OFS                   0x1Cu
#define DMXDESC_NEXT_ADDR_SHIFT            0
#define DMXDESC_NEXT_ADDR_MASK             0xFFFFFFu

/* ---- Named numbers */
#define TEXTCELL_CHAR_SHIFT                0x0u
#define TEXTCELL_FG_SHIFT                  0x8u
#define TEXTCELL_BG_SHIFT                  0xCu
#define SYSID_MAGIC                        0x5236384Bu  /* R68K */
#define WDKICK_MAGIC                       0x5A5Au
#define SYSRESET_MAGIC                     0xA55Au
#define VECBASE_DEFAULT                    0x40u
#define INT_VBLANK                         0x0u
#define INT_LINE                           0x1u
#define INT_COPPER                         0x2u
#define INT_VIDERR                         0x3u
#define INT_DMA0                           0x4u
#define INT_DMA1                           0x5u
#define INT_DMA2                           0x6u
#define INT_DMA3                           0x7u
#define INT_AUDIO                          0x9u
#define INT_TIMER0                         0xBu
#define INT_TIMER1                         0xCu
#define INT_TIMER2                         0xDu
#define INT_TIMER3                         0xEu
#define INT_SERIAL                         0xFu
#define INT_SD                             0x10u
#define INT_KEYB                           0x11u
#define INT_SOFT                           0x12u
#define INTB_VBLANK                        0x0u  /* bit of source 0 in INTENA, INTPEND and INTRAW */
#define INTB_LINE                          0x1u  /* bit of source 1 in INTENA, INTPEND and INTRAW */
#define INTB_COPPER                        0x2u  /* bit of source 2 in INTENA, INTPEND and INTRAW */
#define INTB_VIDERR                        0x3u  /* bit of source 3 in INTENA, INTPEND and INTRAW */
#define INTB_DMA0                          0x4u  /* bit of source 4 in INTENA, INTPEND and INTRAW */
#define INTB_DMA1                          0x5u  /* bit of source 5 in INTENA, INTPEND and INTRAW */
#define INTB_DMA2                          0x6u  /* bit of source 6 in INTENA, INTPEND and INTRAW */
#define INTB_DMA3                          0x7u  /* bit of source 7 in INTENA, INTPEND and INTRAW */
#define INTB_AUDIO                         0x9u  /* bit of source 9 in INTENA, INTPEND and INTRAW */
#define INTB_TIMER0                        0xBu  /* bit of source 11 in INTENA, INTPEND and INTRAW */
#define INTB_TIMER1                        0xCu  /* bit of source 12 in INTENA, INTPEND and INTRAW */
#define INTB_TIMER2                        0xDu  /* bit of source 13 in INTENA, INTPEND and INTRAW */
#define INTB_TIMER3                        0xEu  /* bit of source 14 in INTENA, INTPEND and INTRAW */
#define INTB_SERIAL                        0x10u  /* bit of source 15 in INTENA, INTPEND and INTRAW */
#define INTB_SD                            0x11u  /* bit of source 16 in INTENA, INTPEND and INTRAW */
#define INTB_KEYB                          0x12u  /* bit of source 17 in INTENA, INTPEND and INTRAW */
#define INTB_SOFT                          0x13u  /* bit of source 18 in INTENA, INTPEND and INTRAW */
#define VEC_NMI                            0x1Fu
#define VEC_SPURIOUS                       0x18u
#define DMX_OP_COPY                        0x0u
#define DMX_OP_FILL                        0x1u
#define DMX_OP_KEYCOPY                     0x2u
#define DMX_OP_LOGIC                       0x3u
#define DMX_OP_ADD                         0x4u
#define DMX_OP_MIX                         0x5u
#define DMX_OP_REGLIST                     0x6u
#define DMX_KIND_MEM                       0x0u
#define DMX_KIND_PORT                      0x1u
#define DMX_KIND_NONE                      0x2u
#define DMX_KIND_VALUE                     0x3u
#define DMX_PORT_SD                        0x0u
#define DMX_PORT_SERIAL                    0x1u
#define COP_EXT                            0x80000000u  /* bit 31: 0 = MOVE, 1 = WAIT, SKIP, JUMP or STOP */
#define COP_OP_SHIFT                       0x1Cu  /* bits 30-28: the instruction */
#define COP_OP_WAIT                        0x0u
#define COP_OP_SKIP                        0x1u
#define COP_OP_JUMP                        0x2u
#define COP_OP_STOP                        0x3u
#define COP_PIXONLY                        0x8000000u  /* bit 27: WAIT/SKIP compare the pixel position only */
#define COP_BLT                            0x8000u  /* bit 15: WAIT also waits for the DMA engine to be idle */
#define COP_V_SHIFT                        0x10u
#define COP_H_SHIFT                        0x0u
#define COP_OP_MOVR                        0x4u  /* MOVE through X and Y */
#define COP_OP_ALU                         0x5u
#define COP_OP_SKIPC                       0x6u  /* SKIP on a condition */
#define COP_OP_CALL                        0x7u  /* CALL and RET */
#define COP_MR_A                           0x8000000u  /* MOVR bit 27: the register offset is X */
#define COP_MR_S                           0x4000000u  /* MOVR bit 26: the data is a copper register (bit 24) */
#define COP_MR_I                           0x2000000u  /* MOVR bit 25: X goes up by 2 afterwards */
#define COP_MR_X                           0x1000000u  /* MOVR bit 24: the data register is X (else Y) */
#define COP_FN_SHIFT                       0x19u  /* ALU bits 27-25: the function */
#define COP_FN_LD                          0x0u
#define COP_FN_ST                          0x1u
#define COP_FN_ADD                         0x2u
#define COP_FN_SUB                         0x3u
#define COP_FN_AND                         0x4u
#define COP_FN_OR                          0x5u
#define COP_FN_CMP                         0x6u
#define COP_D_SHIFT                        0x17u  /* ALU bits 24-23: the register: 0 X, 1 Y, 3 flags */
#define COP_S_SHIFT                        0x15u  /* ALU bits 22-21: the source: 0 immediate, 1 X, 2 Y, 3 Rn (n in bits 2-0) */
#define COP_CC_SHIFT                       0x18u  /* SKIPC bits 27-24: the condition */
#define COP_CC_EQ                          0x0u
#define COP_CC_NE                          0x1u
#define COP_CC_LO                          0x2u
#define COP_CC_HS                          0x3u
#define COP_CC_MI                          0x4u
#define COP_CC_PL                          0x5u
#define COP_CC_HI                          0x6u
#define COP_CC_LS                          0x7u
#define COP_RET                            0x8000000u  /* CALL bit 27: RET */
#define COP_STACK                          0x8u  /* stack depth */

#endif /* RETRO68K_HW_H */
